// Get call logs and candidates
const callLogs = $('Read Call Log from Sheets').all();
const candidatesData = $('Get Candidates from Folder').first().json.candidates || [];

// Helper function to normalize phone number (remove spaces, dashes, +, etc.)
function normalizePhone(phone) {
  if (!phone) return '';
  return phone.toString().replace(/[\s\-\+\(\)]/g, '').slice(-9);
}

// Create a map of phone (normalized) to transcript
const transcriptMap = {};

for (const call of callLogs) {
  // Get phone from call log
  const phone = call.json.phone || call.json.from || call.json.to || '';
  const transcript = call.json.transcript;

  if (phone && transcript) {
    const normalizedPhone = normalizePhone(phone);
    if (normalizedPhone) {
      transcriptMap[normalizedPhone] = transcript;
    }
  }
}

// Match candidates with transcriptions by mobile
const results = [];

for (const candidate of candidatesData) {
  // Get mobile from candidate
  const candidateMobile = candidate.mobile || '';

  const normalizedPhone = normalizePhone(candidateMobile);

  // Find matching transcript
  const transcription = transcriptMap[normalizedPhone] || '';

  // Only include candidates that have a matching transcript
  if (transcription) {
    results.push({
      json: {
        candidateId: candidate.candidateId,
        firstName: candidate.firstName,
        lastName: candidate.lastName,
        email: candidate.email,
        mobile: candidateMobile,
        transcript: transcription
      }
    });
  }
}

return results;
